import pathlib,json,html,zipfile
P=pathlib.Path('dev/phase11');season=json.load(open(P/'season-results.json'));rows=json.load(open(P/'ending-comparisons.json'));real=json.load(open(P/'real-timing.json'));sim=json.load(open(P/'sim-timing.json'));unc=json.load(open(P/'timing-uncertainty.json'));decision=json.load(open(P/'decision.json'))
assert all(len(season[k]['seeds'])==5 for k in ['phase10pair','phase11hold','phase11hq'])
assert len(rows)==165 and all(x['n']==2000 for x in rows)
lines=['Hoops Dynasty — Phase 11: Final-minute and overtime audit','21 October 2026','',decision['summary'],'','Full-season NBA comparison','Five independent full 82-game seasons per arm, seeds 101–105; 6,150 games per arm. Same initial seeds, not identical later career paths after changed results/RNG use. Phase10 remains the accepted baseline; its roster allocation and transition changes are preserved.','Metric | Phase10 | Hold | Hold+quick two']
for k in ['points','margin','blow20','OT','teamSD']:lines.append(k+' | '+' | '.join(f"{season[a]['means'][k]:.3f}"for a in ['phase10pair','phase11hold','phase11hq']))
lines+=['','Target: OT 4.5–5.5%. Prespecified practical margin-preservation tolerances: +/-0.25point mean margin and +/-1percentage point20+rate. Point-estimate tolerances are not proof of statistical equivalence.','All seasons were completed without changing production during the test. No result caps, forced ties, accuracy boosts or hidden score corrections were introduced.']
for label in ['phase11hold','phase11hq']:
 lines+=['',label+' seed-level results','Seed | Games | Points/team | Mean margin |20+% |OT% |Team margin SD']
 for r in season[label]['seeds']:lines.append(f"{r['seed']} | {r['n']} | {r['points']:.3f} | {r['margin']:.3f} | {r['blow20']:.3f} | {r['OT']:.3f} | {r['teamSD']:.3f}")
 lines+=['Paired seed differences vs Phase10, approximate95% t intervals(df4):']
 for k,v in season[label]['differences'].items():lines.append(f"{k}: {v['mean']:+.3f}, CI {v['pairedSeedCI95'][0]:+.3f} to {v['pairedSeedCI95'][1]:+.3f}")
lines+=['','Late-game arms:132,000 synthetic endings','Six arms × 11 scenarios × 2,000 seeds. Existing original 8 scenarios plus ties at60/30/20 seconds. Seeds 70000–71999, paired across arms;half retain the earlier lower-three-point-skill fixture. These are synthetic starting scores, not real completed games. They reuse the actual possession, shooting, foul, rebound and OT resolvers.','Arms: production; expanded fouling/repeat nonbonus fouls; quick-two shot selection; timeout/advance approximation; combined old three arms; hold for last shot.','Primary reported endpoints: OT, eventual win, avoiding regulation defeat. Exact paired discordant-outcome tests; Holm adjustment over 165 arm/scenario/endpoint comparisons. Paired difference95% CIs are descriptive and are not simultaneous intervals. Final wins and OT are overlapping outcomes. No promotion is justified solely by an uncorrected isolated p-value.','Scenario | Arm | Baseline OT% | Arm OT% | Difference pp | Paired95%CI pp | Holm p']
for r in rows:
 if r['metric']=='ot':lines.append(f"{r['scenario']} | {r['arm']} | {100*r['baseline']:.2f} | {100*r['candidate']:.2f} | {100*r['difference']:+.2f} | {100*r['ci95'][0]:+.2f} to {100*r['ci95'][1]:+.2f} | {r['holmP']:.6g}")
lines+=['','All statistically significant corrected outcomes, including harms:']
for r in rows:
 if r['holmP']<.05:lines.append(f"{r['arm']} {r['scenario']} {r['metric']}: {100*r['baseline']:.2f}% -> {100*r['candidate']:.2f}%; Holm p={r['holmP']:.6g}")
lines+=['','Bonus-state sensitivity:4 scenarios × 2,000 seeds × 2 arms = 16,000 additional endings. The baseline and combined arm begin already in the foul penalty. Separate evidence is included; exploratory comparisons are not used to claim a production benefit.','Timeout advancement remains approximate: no explicit inbound coordinates and incomplete mandatory-timeout inventory. It cannot be promoted as a complete rules implementation merely because one fixture improves. Expanded fouling is not automatically beneficial; early fouls can trade defensive chances for opponent free throws.','','Final-minute possession timing','The retained official NBA PBP sample has134 score-validated games; 52 were within 6 points at 60 seconds. Simulation:1,000 reset full games; 313 within 6 at 60 seconds. These are availability/repeated-fixture samples, not matched real-versus-sim leagues.','Metric | Simulation | Real sample']
for k in ['meanStartsFinal60','completedDurationsN','meanDuration','medianDuration','tiedUnder24WithShot','tiedLastShotUnder4']:lines.append(f"{k} | {sim[k]} | {real[k]}")
lines+=['Completed possession duration by score state(seconds):']
for k in ['tied','leading','trailing']:lines.append(k+' | '+str(sim['durationByState'][k])+' | '+str(real['durationByState'][k]))
lines+=['Game-cluster bootstrap95% intervals(5,000 resamples):',json.dumps(unc),'Definition: regulation final 60 seconds, games within 6 at 60. Count possessions starting in the window; duration uses completed positive-time possessions, excludes all period-boundary endings in both samples and ambiguous ownership changes. ORBs retain control, FTs consume no game-clock time, defensive rebounds and turnovers switch control. Real team rebounds/retained-ball exceptions can be imperfect;4 final-minute inferred ownership changes were excluded from duration estimates. 134 validated games are retained; 52 qualify for this timing comparison.','Simulation possession starts include control retained through offensive rebounds. The comparison measures game-clock time, not real-world stoppage time. The timing gap is concentrated in leading/trailing possessions; tied durations are similar. It does not justify a universal clock-speed multiplier.','The real sample has only 5 games tied at 60 seconds, 1 reaching OT (20%). Phase 10 has 154 such games, 33 reaching OT (21.43%). The previously cited18%was from an earlier baseline. This conditional statistic is not the full-season OT rate.','Under 24 seconds, explicit hold logic is absent in Phase10. In the observed eligible shot sample, real 5/5 and simulation 15/22 first attempts occurred with<=4seconds left. Those small counts do not establish a precise real-world hold probability. The candidate explicitly reserves 4 seconds for the shot when tied and the shot clock covers the remaining period. It can still miss, turn over, foul or leave an opponent reply; a tie or winner is never forced.','','Promotion decision and limits',json.dumps(decision,indent=2),'','Verification','Promoted source equivalence: 10 full NBA games exactly match the tested candidate. Scope checks: 20 full games across NBA 1997 and WNBA 1997/2006/2024 exactly match the unchanged baseline. No save-schema changes.','Candidate timing-plan constraints: 1,800 combinations. Historical format smoke check: 50 full games acrossNBA 1997/2025, WNBA 1997/2006/2024. Score/box identities, chronological events, nonnegative stats, legal winners and accumulated minutes passed. These are format tests, not historical statistical calibration.','The extra 2,000 tied-at-20 hold checks accounted for every initial possession: 1,566 field-goal attempts, 161 free-throw sequences, 273 turnovers, and zero unexplained no-outcome expirations. Two full-season workers were memory-terminated; their incomplete runs were discarded and their seeds rerun. The runner now treats signal exits as failures. No partial season enters the reported results.','Completed baseline scores, boxes and summary records survive save/load under the candidate. Custom-city-photo hashes and unchanged production source files are checked separately. Existing completed games are not re-simulated.']
if(P/'wnba-results.json').exists():lines+=['','WNBA full-season regression results',json.dumps(json.load(open(P/'wnba-results.json')),indent=2)]
lines+=['','Reproducibility','Baseline source commit45924112bc23ea18cdb71d0f6ab1b8a9a9f639bb. Baseline late-game/attributes/tendencies snapshots in dev/phase11/baseline-dist. Candidate transforms expect baseline anchors; do not apply twice to promoted files.','Synthetic:node dev/run-phase11-endings.cjs;node dev/run-phase11-bonus.cjs. FullNBA:node dev/run-phase11-seasons.cjs;node dev/run-phase11-seasons.cjs dev/phase11/hold-quick.cjs phase11hq. WNBA:node dev/run-phase11-wnba.cjs. Timing:node dev/phase11-timing-matches.cjs nba league 1000 607 production. Analysis scripts and raw outputs retained in dev/phase11 and dev/balance-audit.','Official PBP source: https://stats.nba.com/stats/playbyplayv3?GameID=<ID>&StartPeriod=0&EndPeriod=0. Original game IDs and retrieval provenance retained in dev/phase6/reference-pbp and reference-pbp-fetch.json. No new invented reference data.']
